effect.shader:
#define PI 3.14159265359
vec2 applyTile(vec2 uv, int mode) {
if (mode == 1) {
return fract(uv);
} else if (mode == 2) {
vec2 m = mod(uv, 2.0);
return mix(m, 2.0 - m, step(1.0, m));
} else if (mode == 3) {
return clamp(uv, 0.0, 1.0);
}
return uv;
}
void main() {
vec2 luv = acLayerNorm.xy;
vec2 suv = acScreenNorm.xy;
vec2 uv;
vec2 aspect;
if(followLayer) {
uv = luv;
aspect = vec2(acLayerSize.x / acLayerSize.y, 1.0);
} else {
uv = suv;
aspect = vec2(acScreenSize.x / acScreenSize.y, 1.0);
}
vec2 p = uv * 2.0 - 1.0;
float hDist = hDistortion * 0.01;
float vDist = vDistortion * 0.01;
p.x *= (1.0 - vDist * p.y);
p.y *= (1.0 - hDist * p.x);
if (warpVertical) {
p = p.yx;
}
float b = bend * 0.01;
vec2 warped = p;
int style = int(warpStyle);
int tMode = int(tileMode);
float curve = (1.0 - p.x * p.x);
if (style == 0) {
warped.y += b * curve;
}
else if (style == 1) {
if (p.y < 0.0) warped.y += b * curve * (abs(p.y));
}
else if (style == 2) {
if (p.y > 0.0) warped.y += b * curve * p.y;
}
else if (style == 3) {
warped.y += b * curve;
warped.x *= (1.0 - b * 0.5 * (1.0 + p.y));
}
else if (style == 4) {
float bulge = b * (1.0 - abs(p.x)) * (1.0 - abs(p.y));
warped *= (1.0 - bulge);
}
else if (style == 5) {
warped.y += b * curve;
warped.x *= (1.0 + b * 0.5 * (1.0 - p.y));
}
else if (style == 6) {
warped.y += b * curve;
warped.x *= (1.0 + b * 0.5 * (1.0 + p.y));
}
else if (style == 7) {
warped.y += b * sin(p.x * PI + 0.0);
}
else if (style == 8) {
warped.y += b * sin(p.x * PI * 2.0);
}
else if (style == 9) {
warped.y *= (1.0 + b * p.x);
warped.x += b * 0.2 * (1.0 - p.y * p.y);
}
else if (style == 10) {
warped.y += b * sin(p.x * PI * 0.5);
}
else if (style == 11) {
float d = length(p);
warped = p * (1.0 + b * d);
}
else if (style == 12) {
float d = length(p);
warped = p / (1.0 + b * (1.0 - d));
}
else if (style == 13) {
float d = length(p);
float angle = b * PI * (1.0 - d);
float s = sin(angle), c = cos(angle);
warped = vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}
else if (style == 14) {
warped.x *= (1.0 + b * (1.0 - abs(p.y)));
warped.y *= (1.0 + b * (1.0 - abs(p.x)));
}
if (warpVertical) {
warped = warped.yx;
}
vec2 finalUV = (warped + 1.0) * 0.5;
vec2 tiledUV = applyTile(finalUV, tMode);
vec4 color = texture2DCv(inputImg.texture, tiledUV);
if (tMode == 0) {
if (finalUV.x < 0.0 || finalUV.x > 1.0 || finalUV.y < 0.0 || finalUV.y > 1.0) {
color = vec4(0.0);
}
}
vec4 base = texture2DCv(inputImg.texture, suv);
gl_FragColor = mix(base, color, blend);
}
